class Inventory:
    def __init__(self):
        self._stock = {}          # composition: the dict is an implementation detail

    def add(self, sku, qty):
        self._stock[sku] = self._stock.get(sku, 0) + qty
        return self._stock[sku]

    def remove(self, sku, qty):
        have = self._stock.get(sku, 0)
        if qty > have:
            return False
        if qty == have:
            del self._stock[sku]
        else:
            self._stock[sku] = have - qty
        return True

    def count(self, sku):
        return self._stock.get(sku, 0)

    def __len__(self):
        return len(self._stock)

    def __contains__(self, sku):
        return sku in self._stock

    def __iter__(self):
        return iter(sorted(self._stock))

    def __repr__(self):
        return f'Inventory({self._stock!r})'


def run_inventory(ops):
    inv = Inventory()
    out = []
    for op, *args in ops:
        match op:
            case 'add':
                out.append(inv.add(*args))
            case 'remove':
                out.append(inv.remove(*args))
            case 'count':
                out.append(inv.count(*args))
            case 'has':
                out.append(args[0] in inv)
            case 'size':
                out.append(len(inv))
            case 'list':
                out.append(list(inv))
            case _:
                raise ValueError(f'unknown op {op!r}')
    return out

The class owns the rules (no negative stock, zero-quantity SKUs vanish) and the dict is private, so callers cannot bypass them. Defining `__len__`, `__contains__` and `__iter__` lets the driver use plain `len`, `in` and `list`, exactly like a built-in container. Each operation is O(1) on average except `list`, which sorts: O(k log k) for k SKUs.

