from dataclasses import dataclass, field


@dataclass
class Account:
    owner: str
    balance: int = 0
    history: list = field(default_factory=list)

    def apply(self, amount):
        self.balance += amount
        self.history.append(amount)


def run_bank(ops):
    accounts = {}
    out = []
    for op, *args in ops:
        if op == 'open':
            name = args[0]
            created = name not in accounts
            if created:
                accounts[name] = Account(name)
            out.append(created)
        elif op == 'deposit':
            name, amount = args
            accounts[name].apply(amount)
            out.append(accounts[name].balance)
        elif op == 'withdraw':
            name, amount = args
            account = accounts[name]
            if amount > account.balance:
                out.append(None)
            else:
                account.apply(-amount)
                out.append(account.balance)
        elif op == 'transfer':
            src, dst, amount = args
            if amount > accounts[src].balance:
                out.append(False)
            else:
                accounts[src].apply(-amount)
                accounts[dst].apply(amount)
                out.append(True)
        elif op == 'history':
            out.append(list(accounts[args[0]].history))
    return out

